def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[float('-inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # Starting point

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k is the neutralization count
                if i > 0:
                    # Coming from the top
                    new_coins = dp[i-1][j][k] + coins[i][j]
                    if coins[i][j] < 0:
                        if k > 0:
                            new_coins = max(new_coins, dp[i-1][j][k-1] + coins[i][j])
                    dp[i][j][k] = max(dp[i][j][k], new_coins)
                if j > 0:
                    # Coming from the left
                    new_coins = dp[i][j-1][k] + coins[i][j]
                    if coins[i][j] < 0:
                        if k > 0:
                            new_coins = max(new_coins, dp[i][j-1][k-1] + coins[i][j])
                    dp[i][j][k] = max(dp[i][j][k], new_coins)

    return max(dp[m-1][n-1][0], dp[m-1][n-1][1], dp[m-1][n-1][2])

from typing import List

def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    from collections import defaultdict, deque
    import sys

    def canReachZero(maxWeight):
        graph = defaultdict(list)
        for u, v, w in edges:
            if w <= maxWeight:
                graph[v].append(u)

        queue = deque([0])
        visited = set([0])

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        return len(visited) == n

    def countOutgoingEdges(maxWeight):
        outgoingCount = [0] * n
        for u, v, w in edges:
            if w <= maxWeight:
                outgoingCount[u] += 1
                if outgoingCount[u] > threshold:
                    return False
        return True

    left, right = 1, 10**6
    bestWeight = sys.maxsize

    while left <= right:
        mid = (left + right) // 2

        if canReachZero(mid) and countOutgoingEdges(mid):
            bestWeight = mid
            right = mid - 1
        else:
            left = mid + 1

    return bestWeight if bestWeight != sys.maxsize else -1

from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize a DP array to store the minimum cost for painting up to each house.
    dp = [[0] * 3 for _ in range(n)]

    # Base case: for the first house, the cost is just the painting costs.
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the DP table for each house from the second to the last.
    for i in range(1, n):
        for j in range(3):
            # Cost for painting house i with color j
            # Ensure to not paint the previous house (i-1) the same color
            dp[i][j] = cost[i][j] + min(dp[i-1][(j+1) % 3], dp[i-1][(j+2) % 3])

    # Handle equidistant constraints
    min_cost = float('inf')
    for first_color in range(3):
        for second_color in range(3):
            if second_color != first_color:
                total_cost = dp[n-1][second_color] + dp[n//2 - 1][(first_color + 1) % 3]
                min_cost = min(min_cost, total_cost)
    return min_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in sorted(events, key=lambda x: int(x[1])):
        event_type, timestamp, *details = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(details[0])
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            # Process offline users who come back online before this message
            for user_id in range(numberOfUsers):
                if not online_status[user_id] and offline_until[user_id] <= timestamp:
                    online_status[user_id] = True

            mentions_string = details[0]
            if mentions_string == "ALL":
                for user_id in range(numberOfUsers):
                    mentions[user_id] += 1
            elif mentions_string == "HERE":
                for user_id in range(numberOfUsers):
                    if online_status[user_id]:
                        mentions[user_id] += 1
            else:
                mentioned_ids = mentions_string.split()
                for mention in mentioned_ids:
                    user_id = int(mention[2:])  # Get the id from "id<number>"
                    mentions[user_id] += 1

    return mentions

from typing import List


def maxFreeTime(eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
    n = len(startTime)
    last_end = 0
    free_intervals = []

    # Collect existing free intervals
    for start, end in zip(startTime, endTime):
        if start > last_end:
            free_intervals.append((last_end, start))
        last_end = end

    if last_end < eventTime:
        free_intervals.append((last_end, eventTime))

    # Initialize maximum free time from collected intervals
    max_free_time = 0
    for free_start, free_end in free_intervals:
        max_free_time = max(max_free_time, free_end - free_start)

    # To find max free time after rescheduling, we can calculate gaps to consider moving meetings
    moveable_meetings = []
    for i in range(n):
        meeting_duration = endTime[i] - startTime[i]
        if i > 0:
            gap_left = startTime[i] - endTime[i-1]
            if gap_left >= meeting_duration:
                moveable_meetings.append((gap_left, i, meeting_duration))
        else:
            if startTime[i] >= meeting_duration:
                moveable_meetings.append((startTime[i], i, meeting_duration))

    moveable_meetings.sort(reverse=True)  # Sort to prioritize larger gaps first

    # Reschedule meetings to create maximum free time
    for _ in range(k):
        if moveable_meetings:
            _, index, duration = moveable_meetings.pop(0)
            new_start = endTime[index - 1] if index > 0 else 0
            new_end = new_start + duration
            startTime[index] = new_start
            endTime[index] = new_end

            # Recalculate free intervals after potential meeting move
            last_end = 0
            new_free_intervals = []
            for start, end in zip(startTime, endTime):
                if start > last_end:
                    new_free_intervals.append((last_end, start))
                last_end = end
            if last_end < eventTime:
                new_free_intervals.append((last_end, eventTime))

            # Determine the maximum free time after rescheduling
            for free_start, free_end in new_free_intervals:
                max_free_time = max(max_free_time, free_end - free_start)

    return max_free_time
